"use strict";
/* ============================ Dados físicos ============================ */
const DEG = Math.PI / 180;

// Raios orbitais em AU (Terra = 1) e períodos (dias).
const BODIES = [
  { name:"Mercury", au:0.3871, period:87.969,  a0:210,   color:"#c9b27e", pr:2.6, label:"Mercúrio" },
  { name:"Venus",   au:0.7233, period:224.701, a0:330,   color:"#e6c26a", pr:4.4, label:"Vénus"    },
  { name:"Earth",   au:1.0,    period:365.25,  a0:0,     color:"#4d9df0", pr:4.8, label:"Terra"    },
  { name:"Mars",    au:1.5237, period:686.98,  a0:0,     color:"#e06a42", pr:3.4, label:"Marte"    },
];
const EARTH = BODIES[2], MARS = BODIES[3];
const PE = EARTH.period, PM = MARS.period;   // 365.25 e 686.98 dias → 1.88 anos
const RE = EARTH.au,    RM = MARS.au;        // 1.0 e 1.5237 AU
const NE = 360 / PE,    NM = 360 / PM;       // graus/dia

/* ============ Geometria da missão (Hohmann) — auto-consistente ============
   Ida: elipse de Hohmann com periélio em r=RE e afélio em r=RM, semieixo
   a=(RE+RM)/2. Meio período => ~259 dias (T_OUT).
   À partida a nave fica em ângulo 0 (posição da Terra); chega em +180°,
   logo Marte deve estar lá: fase = 180 - T_OUT*NM ≈ 44.3°.
   Regresso: elipse idêntica a partir de RM. Se a partida de regresso for
   RET_START, a nave chega em RET_START + T_RET a RET_start_âng+180 e a Terra
   tem de estar lá:  2*T_OUT*NE ≡ STAY*(NM-NE) (mod 360)  →  STAY ≈ 453.7 d
   (≈ "455 dias"), total ≈ 971.8 d (≈ "970 dias"). Todas as chegadas são
   EXATAS por construção. */
const T_OUT = 259.0, T_RET = 259.0;
const PHASE = 180 - T_OUT * NM;                    // ângulo de partida (graus)
MARS.a0 = ((PHASE % 360) + 360) % 360;             // ângulo de Marte no dia 0
const SYN = 360 / (NE - NM);                       // período sinódico (~779.9 d)
let STAY = (2 * T_OUT * NE) / (NM - NE);
while (STAY < 0) STAY += SYN;
const RET_START = T_OUT + STAY;
const TOTAL = T_OUT + STAY + T_RET;

/* =================== Posições determinísticas (concorrência) =================== */
function bodyAngleDeg(b, day) { return (b.a0 + 360 * day / b.period) % 360; }
function bodyPosAU(b, day) {
  const a = bodyAngleDeg(b, day) * DEG;
  return { x: b.au * Math.cos(a), y: b.au * Math.sin(a) };
}

// Elipse de Hohmann (Kepler): M = π·t/T, resolver M = E - e·sinE por Newton.
const A_T = (RE + RM) / 2, E_T = (RM - RE) / (RM + RE), P_T = A_T * (1 - E_T * E_T);
function keplerE(Mmean, e) {
  let Ee = Mmean;
  for (let i = 0; i < 50; i++) {
    const f = Ee - e * Math.sin(Ee) - Mmean, dp = 1 - e * Math.cos(Ee);
    const d = f / dp; Ee -= d;
    if (Math.abs(d) < 1e-15) break;
  }
  return Ee;
}
function fTrue(Ee, e) {
  return 2 * Math.atan2(Math.sqrt(1 + e) * Math.sin(Ee / 2), Math.sqrt(1 - e) * Math.cos(Ee / 2));
}
// tfrac em [0,1]; outbound: periélio primeiro (r: RE→RM); inbound: afélio primeiro (RM→RE)
function transferPoint(tfrac, outbound) {
  const f = fTrue(keplerE(Math.PI * Math.min(Math.max(tfrac, 0), 1), E_T), E_T);
  const r = P_T / (outbound ? 1 + E_T * Math.cos(f) : 1 - E_T * Math.cos(f));
  return { r, f };
}
function shipPos(day) {
  if (day <= 0) return bodyPosAU(EARTH, day);
  if (day < T_OUT) {
    const { r, f } = transferPoint(day / T_OUT, true);
    return { x: r * Math.cos(f), y: r * Math.sin(f) };
  }
  if (day < RET_START) return bodyPosAU(MARS, day);
  if (day < TOTAL) {
    const dep = bodyAngleDeg(MARS, RET_START) * DEG;
    const { r, f } = transferPoint((day - RET_START) / T_RET, false);
    const a = dep + f;
    return { x: r * Math.cos(a), y: r * Math.sin(a) };
  }
