document.querySelectorAll("[data-jump]").forEach(b =>
  b.addEventListener("click", () => { simDay = Number(b.dataset.jump); }));
$("btnPlay").addEventListener("click", () => {
  playing = !playing;
  $("btnPlay").textContent = playing ? "⏸ Pausa" : "▶ Reproduzir";
});
$("btnReset").addEventListener("click", () => { simDay = 0; });
$("speed").addEventListener("input", e => {
  speed = Number(e.target.value);
  $("speedVal").textContent = speed.toFixed(1) + " dias/s";
});
function updateHUD() {
  const d = simDay;
  $("hudDay").textContent = fmt(d) + " / " + fmt(TOTAL);
  let ph;
