  else ph = "Missão concluída" + (d > TOTAL + 0.5 ? " (+" + fmt(d - TOTAL) + " d)" : "");
  $("hudPhase").textContent = ph;
  $("fpsNow").textContent = fpsInstant.toFixed(1);
  $("fpsAvg").textContent = fpsAvg.toFixed(1);
}

/* ============================ Renderização ============================ */
const cv = $("cv"), ctx = cv.getContext("2d");
const stars = Array.from({ length: 240 }, () => ({
  x: Math.random(), y: Math.random(), r: Math.random() * 1.1 + 0.3, a: Math.random() * 0.5 + 0.25
}));

function resize() {
  const dpr = window.devicePixelRatio || 1;
  cv.width = Math.round(innerWidth * dpr);
  cv.height = Math.round(innerHeight * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener("resize", resize);
resize();

function project(xAu, yAu, w, h) {
  const F = (Math.min(w, h) / 2 - 34) / (RM * 1.04); // px por AU (Marte + folga)
  return [w / 2 + xAu * F, h / 2 - yAu * F, F];
}

function polyAU(pts, style, dash) {
  ctx.save();
  ctx.strokeStyle = style; ctx.lineWidth = 1.2;
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath();
  pts.forEach((p, i) => { const [x, y] = project(p.x, p.y, innerWidth, innerHeight); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
  ctx.stroke(); ctx.restore();
}
function samplePath(fn, d0, d1, n) {
  const pts = []; for (let i = 0; i <= n; i++) pts.push(fn(d0 + (d1 - d0) * i / n)); return pts;
}

function render() {
  const w = innerWidth, h = innerHeight, cx = w / 2, cy = h / 2;
  const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(w, h) * 0.7);
  bg.addColorStop(0, "#0a1020"); bg.addColorStop(1, "#04060d");
  ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
  for (const s of stars) { ctx.globalAlpha = s.a; ctx.fillStyle = "#cfe2ff";
    ctx.beginPath(); ctx.arc(s.x * w, s.y * h, s.r, 0, 7); ctx.fill(); }
  ctx.globalAlpha = 1;

  // Órbitas circulares
  for (const b of BODIES) {
    const [x, y, F] = project(b.au, 0, w, h);
    ctx.beginPath(); ctx.arc(cx, cy, b.au * F, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(140,170,220,.28)"; ctx.lineWidth = 1; ctx.stroke();
  }

  // Trajetórias de Hohmann previstas (tracejadas) e percorridas (contínuas)
  const out = d => shipPos(d), ret = d => shipPos(d);
  polyAU(samplePath(out, 0, T_OUT, 110), "rgba(110,190,255,.28)", [5, 7]);
  polyAU(samplePath(ret, RET_START, TOTAL, 110), "rgba(255,160,100,.28)", [5, 7]);
  const d = simDay;
  if (d > 0.2) polyAU(samplePath(out, 0, Math.min(d, T_OUT), 60), "rgba(140,210,255,.95)");
  if (d > T_OUT + 0.5) polyAU(samplePath(x => bodyPosAU(MARS, x), T_OUT, Math.min(d, RET_START), 60), "rgba(140,210,255,.7)");
  if (d > RET_START + 0.5) polyAU(samplePath(ret, RET_START, d, 60), "rgba(255,190,140,.95)");

  // Sol
  const sunR = 13;
  const sg = ctx.createRadialGradient(cx, cy, 0, cx, cy, sunR * 3.2);
  sg.addColorStop(0, "rgba(255,240,190,1)"); sg.addColorStop(0.35, "rgba(255,190,80,.85)");
  sg.addColorStop(1, "rgba(255,150,40,0)");
  ctx.fillStyle = sg; ctx.beginPath(); ctx.arc(cx, cy, sunR * 3.2, 0, 7); ctx.fill();
  ctx.fillStyle = "#ffd97a"; ctx.beginPath(); ctx.arc(cx, cy, sunR, 0, 7); ctx.fill();

  // Planetas
  ctx.font = "12px system-ui, sans-serif"; ctx.textBaseline = "middle";
  for (const b of BODIES) {
    const p = bodyPosAU(b, d);
    const [x, y] = project(p.x, p.y, w, h);
    ctx.save(); ctx.shadowColor = b.color; ctx.shadowBlur = 8;
    ctx.fillStyle = b.color; ctx.beginPath(); ctx.arc(x, y, b.pr, 0, 7); ctx.fill(); ctx.restore();
    ctx.fillStyle = "rgba(220,235,255,.85)"; ctx.fillText(b.label, x + b.pr + 6, y - b.pr - 4);
  }

  // Nave
  const sp = shipPos(d);
  const [sx, sy] = project(sp.x, sp.y, w, h);
  ctx.save(); ctx.shadowColor = "#9fe8ff"; ctx.shadowBlur = 12;
  ctx.fillStyle = "#ffffff"; ctx.beginPath(); ctx.arc(sx, sy, 3.4, 0, 7); ctx.fill();
  ctx.strokeStyle = "#9fe8ff"; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(sx, sy, 7, 0, 7); ctx.stroke(); ctx.restore();
}

/* ============================ Loop de animação ============================ */
let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 1000, 0.25);
  last = now;
  if (dt > 0) {
    fpsInstant = fpsInstant * 0.85 + (1 / dt) * 0.15;
    fpsFrames++;
    const el = now - fpsT0;
    if (el >= 500) { fpsAvg = fpsFrames / (el / 1000); fpsFrames = 0; fpsT0 = now; }
  }
  if (playing) simDay += dt * speed;
  render();
  updateHUD();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
